import {Box, ButtonGroup, FormControl, Grid, IconButton, MenuItem, Select, SelectChangeEvent} from "@mui/material";
import React, {useCallback, useMemo, useState} from "react";
import {ChartOneWindowIcon, ChartTwoVerticalWindowsIcon, ChartTwoHorizontalWindowsIcon, ChartForWindowsIcon} from "../icons";
import KLineChart from "./KLineChart";
import {MarketChartsProps} from "./MarketCharts.props";

interface ChartIntervalProps {
  windowChart: number;
  interval: string;
  handleIntervalChange: (event: SelectChangeEvent<string>, chart: number) => void
}

const MarketCharts = React.memo(({symbol}: MarketChartsProps) => {
  const [windowsChart, setWindowsChart] = useState<"one" | "twoVertical" | "twoHorizontal" | "for">("for");

  const [IntervalFirstChart, setIntervalFirstChart] = useState("4h");
  const [IntervalSecondChart, setIntervalSecondChart] = useState("1d");
  const [IntervalThirdtChart, setIntervalThirdChart] = useState("5m");
  const [IntervalFourthChart, setIntervalFourthChart] = useState("15m");

  const handleIntervalChange = useCallback((event: SelectChangeEvent<string>, chart: number) => {
    const value = event.target.value;

    switch (chart) {
    case 1:
      setIntervalFirstChart(value);
      break;
    case 2:
      setIntervalSecondChart(value);
      break;
    case 3:
      setIntervalThirdChart(value);
      break;
    case 4:
      setIntervalFourthChart(value);
      break;
    default:
      break;
    }
  },
  []
  );

  const ChartDuration: React.FC<ChartIntervalProps> = React.memo(({windowChart, interval, handleIntervalChange}) => {
    return useMemo(
      () => (
        <Box height="calc(100% - 4px)" p={.5} width="calc(100% - 4px)" borderRadius="8px" sx={{bgcolor: "#fff"}} >
          <FormControl sx={{
            mb: 1, " & .MuiSelect-select": : {paddingY: 1}, "& fieldset": {border: "none"}, height: 31,
            backgroundColor: "#eeeeee", color: "#191919", padding: "0", borderRadius: "8px",
          }}>
            <Select sx={{fontSize: "12px"}} value={interval} onChange={(e) => handleIntervalChange(e, windowChart)}>
              <MenuItem value="1m">1м</MenuItem>
              <MenuItem value="5m">5м</MenuItem>
              <MenuItem value="15m">15м</MenuItem>
              <MenuItem value="1h">1ч</MenuItem>
              <MenuItem value="4h">4ч</MenuItem>
              <MenuItem value="1d">1д</MenuItem>
              <MenuItem value="1w">1н</MenuItem>
            </Select>
          </FormControl>
          <KLineChart symbol={symbol} interval={interval} />
        </Box>
      ),
      []
    );
  });

  ChartDuration.displayName = "ChartDuration";

  return (
    <Grid container height="72%" borderRadius="8px" position="relative">
      <Box position="absolute" top={4} right={8} borderRadius={1} border="1px solid #d4d4d4" height={31} >
        <ButtonGroup>
          <IconButton onClick={() => setWindowsChart("one")} sx={{m: .3, height: 23, width: 23}}><ChartOneWindowIcon sx={{fill: windowsChart === "one" ? "#B41C18" : "#d4d4d4"}} /> </IconButton>
          <IconButton onClick={() => setWindowsChart("twoVertical")} sx={{m: .3, height: 23, width: 23}}><ChartTwoVerticalWindowsIcon sx={{fill: windowsChart === "twoVertical" ? "#B41C18" : "#d4d4d4"}} /></IconButton>
          <IconButton onClick={() => setWindowsChart("twoHorizontal")} sx={{m: .3, height: 23, width: 23}}><ChartTwoHorizontalWindowsIcon sx={{fill: windowsChart === "twoHorizontal" ? "#B41C18" : "#d4d4d4"}} /></IconButton>


